document.querySelectorAll('[data-security-form]').forEach(function(form){const key='tripnest-security-'+form.dataset.securityForm;let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){};Object.entries(saved).forEach(function(entry){const el=form.elements.namedItem(entry[0]);if(el){if(el.type==='checkbox')el.checked=Boolean(entry[1]);else el.value=entry[1]}});form.addEventListener('submit',function(e){e.preventDefault();const data={};new FormData(form).forEach((v,k)=>data[k]=String(v));form.querySelectorAll('input[type=checkbox]').forEach(el=>data[el.name]=el.checked);localStorage.setItem(key,JSON.stringify(data));const status=form.querySelector('.sec-status');if(status)status.textContent='Security settings saved in this browser only. No real accounts or policies were changed.'})});
