document.querySelectorAll('[data-security-confirm]').forEach(function(button){button.addEventListener('click',function(){localStorage.setItem('tripnest-security-last-session-action',JSON.stringify({action:'Force Logout (demo)',time:new Date().toISOString()}));const status=button.closest('.card').querySelector('.sec-status');if(status)status.textContent='Demo session marked for logout locally. No real session was ended.';button.disabled=true;button.textContent='Marked (demo)'})});
document.querySelectorAll('[data-review]').forEach(function(button){button.addEventListener('click',function(){const decision={decision:button.dataset.review,time:new Date().toISOString()};localStorage.setItem('tripnest-security-booking-review',JSON.stringify(decision));const status=button.closest('.card').querySelector('.sec-status');if(status)status.textContent=decision.decision+' recorded locally for the fabricated review case. No booking was changed.'})});

/* Prototype 84: language, currency and accessibility preferences are local demo settings. */
document.querySelectorAll('[data-locale84-form]').forEach(function(form){const key='tripnest-locale84-'+form.dataset.locale84Form;let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){};Object.entries(saved).forEach(function(entry){const el=form.elements.namedItem(entry[0]);if(el){if(el.type==='checkbox')el.checked=Boolean(entry[1]);else el.value=entry[1]}});form.addEventListener('submit',function(e){e.preventDefault();const data={};new FormData(form).forEach((v,k)=>data[k]=String(v));form.querySelectorAll('input[type=checkbox]').forEach(el=>data[el.name]=el.checked);localStorage.setItem(key,JSON.stringify(data));const status=form.querySelector('.loc84-status');if(status)status.textContent='Preferences saved in this browser only. No external service was contacted.';if(form.dataset.locale84Form==='language-selection'){localStorage.setItem('tripnest-language',data.language||'English (EN)');if(status)status.textContent='Language preference saved locally for this demo.'}})});
document.querySelectorAll('[data-locale-choice]').forEach(function(button){button.addEventListener('click',function(){localStorage.setItem('tripnest-locale84-last-choice',button.dataset.localeChoice);button.classList.add('active');const note=document.createElement('p');note.className='notice success';note.textContent=button.dataset.localeChoice+' selected for preview. This does not change account-wide settings.';button.after(note)})});
document.querySelectorAll('[data-locale-confirm]').forEach(function(button){button.addEventListener('click',function(){localStorage.setItem('tripnest-language','हिन्दी (HI)');const status=button.closest('.loc84-dialog').querySelector('.loc84-status');if(status)status.textContent='Hindi selected for this browser demo.';button.disabled=true;button.textContent='Language Changed (demo)'})});

/* Prototype 82: identity and recovery steps are simulated with fabricated data only. */
document.querySelectorAll('[data-id82-form]').forEach(function(form){const key='tripnest-id82-'+form.dataset.id82Form;let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){};Object.entries(saved).forEach(function(entry){const el=form.elements.namedItem(entry[0]);if(el)el.value=entry[1]});form.addEventListener('submit',function(e){e.preventDefault();const data={};new FormData(form).forEach((v,k)=>data[k]=String(v));localStorage.setItem(key,JSON.stringify(data));const status=form.querySelector('.id82-status');if(status)status.textContent='Demo form saved locally. No email, SMS, password reset or document upload was sent to a server.'})});
document.querySelectorAll('[data-id82-verify]').forEach(function(button){button.addEventListener('click',function(){localStorage.setItem('tripnest-id82-'+button.dataset.id82Verify+'-verified','true');const status=button.closest('.id82-verify').querySelector('.id82-status');if(status)status.textContent='Verification marked complete for this demo only. No real contact method was verified.';button.disabled=true;button.textContent='Verified (demo)'})});
document.querySelectorAll('[data-id82-review]').forEach(function(button){button.addEventListener('click',function(){localStorage.setItem('tripnest-id82-review',JSON.stringify({decision:button.dataset.id82Review,time:new Date().toISOString()}));const status=button.closest('.card').querySelector('.id82-status');if(status)status.textContent=button.dataset.id82Review+' saved locally. No real identity record was changed.'})});

/* Prototype 83: ticket, refund and dispute flows are stored locally as demo records. */
document.querySelectorAll('[data-support83-form]').forEach(function(form){form.addEventListener('submit',function(e){e.preventDefault();const data={};new FormData(form).forEach((v,k)=>data[k]=String(v));const key='tripnest-support83-'+form.dataset.support83Form;localStorage.setItem(key,JSON.stringify(data));const status=form.querySelector('.s83-status');if(status)status.textContent='Saved locally for this demo. No real support/refund provider was contacted.';if(form.dataset.next){location.href=form.dataset.next}})});
document.querySelectorAll('[data-support83-choice]').forEach(function(button){button.addEventListener('click',function(){localStorage.setItem('tripnest-support83-selected',JSON.stringify({choice:button.dataset.support83Choice,from:location.pathname}));if(button.dataset.next)location.href=button.dataset.next})});
document.querySelectorAll('[data-support83-submit]').forEach(function(button){button.addEventListener('click',function(){const ticket={id:'#TKT-'+String(Math.floor(10000+Math.random()*89999)),created:new Date().toISOString(),status:'In Review (demo)',booking:JSON.parse(localStorage.getItem('tripnest-support83-support-ticket-create')||'{}'),problem:JSON.parse(localStorage.getItem('tripnest-support83-support-describe-problem')||'{}'),attachment:JSON.parse(localStorage.getItem('tripnest-support83-support-attach-documents')||'{}')};localStorage.setItem('tripnest-support83-ticket',JSON.stringify(ticket));location.href='support-ticket-submitted.html'})});
const ticketIdEl=document.querySelector('[data-support83-ticket-id]');if(ticketIdEl){let ticket={};try{ticket=JSON.parse(localStorage.getItem('tripnest-support83-ticket')||'{}')}catch(e){}ticketIdEl.textContent=ticket.id||'#TKT-DEMO'}
const summary=document.querySelector('[data-support83-summary]');if(summary){const entries=['support-ticket-create','support-describe-problem','support-attach-documents'];summary.textContent=entries.map(k=>{try{return JSON.stringify(JSON.parse(localStorage.getItem('tripnest-support83-'+k)||'{}'))}catch(e){return ''}}).filter(Boolean).join(' · ')||'No demo details entered yet.'}
document.querySelectorAll('[data-support83-next]').forEach(function(button){button.addEventListener('click',function(){localStorage.setItem('tripnest-support83-refund-decision','Initiated (demo)');location.href=button.dataset.support83Next})});
document.querySelectorAll('[data-resolution]').forEach(function(button){button.addEventListener('click',function(){localStorage.setItem('tripnest-support83-resolution',button.dataset.resolution);const status=button.closest('.card').querySelector('.s83-status');if(status)status.textContent=button.dataset.resolution+' recorded locally; no payment or dispute provider was contacted.';if(button.dataset.resolution==='Accepted (demo)')setTimeout(()=>location.href='resolution-accepted.html',250)})});
